_NONCE_SIZE = 12

_K_PARTS = [60, 46, 94, 252, 212, 60, 14, 244, 150, 181, 194, 243, 250, 118, 153, 155, 139, 205, 69, 160, 75, 142, 227, 253, 177, 148, 169, 123, 142, 250, 234, 104]
_K_MASK = [37, 128, 97, 29, 204, 168, 205, 175, 68, 134, 188, 134, 118, 21, 25, 53, 55, 57, 231, 83, 89, 214, 3, 139, 131, 171, 65, 67, 228, 132, 67, 197]

def _rebuild_key():
    parts = _K_PARTS
    mask = _K_MASK
    key = bytes(p ^ m for p, m in zip(parts, mask))
    return key

def _run():
    raw = base64.b85decode(_PAYLOAD)
    nonce, ciphertext = raw[:_NONCE_SIZE], raw[_NONCE_SIZE:]
    key = _rebuild_key()
    aesgcm = AESGCM(key)
    try:
        compressed = aesgcm.decrypt(nonce, ciphertext, None)
    except Exception:
        sys.stderr.write("Corrupted or tampered protected file.\n")
        sys.exit(1)
    raw_bytecode = zlib.decompress(compressed)
    code_obj = marshal.loads(raw_bytecode)
    exec(code_obj, {"__name__": "__main__", "__file__": __file__})

_run()
